<template>
  <div v-loading="loading" class="vendor-result">
    <div class="section"><div class="section-header"><div><h2 class="section-title">供应商接入计费自测结果</h2><p class="subtitle">{{ data?.config?.supplier_name || '-' }} · {{ data?.config?.model || '-' }} 对照 {{ data?.config?.reference_model || '-' }}</p></div><div class="toolbar"><el-button @click="router.push('/tests/vendor-billing')">再次测试</el-button><el-button @click="router.push('/history')">历史记录</el-button><el-dropdown v-if="data?.summary" @command="download"><el-button type="primary">下载报告</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="summary">Summary JSON</el-dropdown-item><el-dropdown-item command="details">Details JSONL</el-dropdown-item><el-dropdown-item command="markdown">Markdown</el-dropdown-item><el-dropdown-item command="html">HTML</el-dropdown-item><el-dropdown-item command="pdf">PDF</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div><div class="section-body"><el-alert v-if="data?.summary" :title="`总体结论：${statusLabel(data.summary.status)}`" :type="alertType(data.summary.status)" :description="statusReason(data.summary)" :closable="false" show-icon /><el-alert v-else :title="`任务${data?.task_status || '未知'}，未形成完整核验结论`" type="warning" :closable="false" show-icon /><p class="subtitle">本版本只核验 Token 上报和目录规则下的应计费用，不核验供应商账户的实际扣费。</p></div></div>
    <div v-if="data?.summary" class="summary-grid"><div class="summary-card"><span>完成组数</span><strong>{{ data.summary.completed_groups }} / {{ data.summary.total_groups }}</strong><em>按输入长度串行执行</em></div><div class="summary-card"><span>通过</span><strong>{{ data.summary.status_counts?.passed || 0 }}</strong><em>输入 Token 在容差内</em></div><div class="summary-card"><span>Token 异常</span><strong>{{ data.summary.status_counts?.token_anomaly || 0 }}</strong><em>输入差异超出容差</em></div><div class="summary-card"><span>无法核验</span><strong>{{ (data.summary.status_counts?.unverifiable || 0) + (data.summary.status_counts?.pricing_unverifiable || 0) }}</strong><em>不使用估算价格判定通过</em></div></div>
    <div v-if="data?.summary" class="section"><div class="section-header"><h2 class="section-title">逐组 Token 与费用对照</h2></div><div class="section-body result-table-wrap"><el-table :data="data.summary.details || []" stripe><el-table-column prop="input_token_target" label="输入目标" width="110" /><el-table-column label="供应商输入 Token"><template #default="scope">{{ token(scope.row.supplier?.input_tokens) }}</template></el-table-column><el-table-column label="官方输入 Token"><template #default="scope">{{ token(scope.row.reference?.input_tokens) }}</template></el-table-column><el-table-column label="输入差值"><template #default="scope">{{ token(scope.row.comparison?.input_token_delta) }}</template></el-table-column><el-table-column label="供应商费用 USD"><template #default="scope">{{ money(scope.row.comparison?.supplier_cost?.total_usd) }}</template></el-table-column><el-table-column label="官方费用 USD"><template #default="scope">{{ money(scope.row.comparison?.reference_cost?.total_usd) }}</template></el-table-column><el-table-column label="状态"><template #default="scope"><el-tag :type="summaryType(scope.row.comparison?.status)" effect="plain">{{ statusLabel(scope.row.comparison?.status) }}</el-tag></template></el-table-column><el-table-column label="依据" min-width="280"><template #default="scope">{{ scope.row.comparison?.reason || '-' }}</template></el-table-column></el-table></div></div>
    <div v-if="data?.summary" class="section"><div class="section-header"><h2 class="section-title">用量明细与价格拆分</h2></div><div class="section-body"><el-collapse><el-collapse-item v-for="item in data.summary.details || []" :key="item.index" :title="`输入 ${item.input_token_target} · ${statusLabel(item.comparison?.status)}`"><el-descriptions :column="3" border><el-descriptions-item label="Token 结论">{{ statusLabel(item.comparison?.token_verification_status) }}</el-descriptions-item><el-descriptions-item label="计价结论">{{ statusLabel(item.comparison?.pricing_verification_status) }}</el-descriptions-item><el-descriptions-item label="总体结论">{{ statusLabel(item.comparison?.overall_status) }}</el-descriptions-item><el-descriptions-item label="供应商总 Token">{{ token(item.supplier?.total_tokens) }}</el-descriptions-item><el-descriptions-item label="供应商缓存读取">{{ token(item.supplier?.cached_input_tokens) }}</el-descriptions-item><el-descriptions-item label="供应商缓存写入">{{ token(item.supplier?.cache_creation_input_tokens) }}</el-descriptions-item><el-descriptions-item label="官方总 Token">{{ token(item.reference?.total_tokens) }}</el-descriptions-item><el-descriptions-item label="官方缓存读取">{{ token(item.reference?.cached_input_tokens) }}</el-descriptions-item><el-descriptions-item label="官方缓存写入">{{ token(item.reference?.cache_creation_input_tokens) }}</el-descriptions-item><el-descriptions-item label="供应商 HTTP / 耗时 / TTFT">{{ item.supplier?.http_status ?? '-' }} / {{ seconds(item.supplier?.latency_sec) }} / {{ seconds(item.supplier?.ttft_sec) }}</el-descriptions-item><el-descriptions-item label="官方 HTTP / 耗时 / TTFT">{{ item.reference?.http_status ?? '-' }} / {{ seconds(item.reference?.latency_sec) }} / {{ seconds(item.reference?.ttft_sec) }}</el-descriptions-item><el-descriptions-item label="接口错误">{{ item.supplier?.error_message || item.reference?.error_message || '-' }}</el-descriptions-item><el-descriptions-item label="供应商输出 Token">{{ token(item.supplier?.output_tokens) }}</el-descriptions-item><el-descriptions-item label="官方输出 Token">{{ token(item.reference?.output_tokens) }}</el-descriptions-item><el-descriptions-item label="输出差值">{{ token(item.comparison?.output_token_delta) }}（仅观察）</el-descriptions-item><el-descriptions-item label="供应商输入费用">{{ money(item.comparison?.supplier_cost?.input_cost_usd) }}</el-descriptions-item><el-descriptions-item label="供应商缓存读取费用">{{ money(item.comparison?.supplier_cost?.cache_read_cost_usd) }}</el-descriptions-item><el-descriptions-item label="供应商缓存写入费用">{{ money(item.comparison?.supplier_cost?.cache_write_cost_usd) }}</el-descriptions-item><el-descriptions-item label="供应商输出费用">{{ money(item.comparison?.supplier_cost?.output_cost_usd) }}</el-descriptions-item><el-descriptions-item label="供应商总费用">{{ money(item.comparison?.supplier_cost?.total_usd) }}</el-descriptions-item><el-descriptions-item label="官方总费用">{{ money(item.comparison?.reference_cost?.total_usd) }}</el-descriptions-item><el-descriptions-item label="Prompt SHA-256">{{ item.prompt_sha256 }}</el-descriptions-item></el-descriptions></el-collapse-item></el-collapse></div></div>
  </div>
</template>
<script setup>
import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { getVendorBilling, vendorBillingDownloadUrl } from '../api/client'
const route = useRoute(); const router = useRouter(); const id = route.params.id; const data = ref(null); const loading = ref(true)
function token(value) { return value === undefined || value === null ? '不可核验' : Number(value).toLocaleString() }; function money(value) { return value === undefined || value === null ? '不可核验' : Number(value).toFixed(8) }
function seconds(value) { return value === undefined || value === null ? '不可用' : `${Number(value).toFixed(3)}s` }
function statusLabel(value) { return ({ passed: '通过', token_anomaly: 'Token 异常', pricing_unverifiable: '计价规则无法核验', failed: '接口执行失败', unverifiable: '无法核验', cancelled: '已取消' }[value] || value || '-') }; function summaryType(value) { return value === 'passed' ? 'success' : value === 'failed' || value === 'token_anomaly' ? 'danger' : 'warning' }; function alertType(value) { return value === 'passed' ? 'success' : value === 'failed' || value === 'token_anomaly' ? 'error' : 'warning' }; function statusReason(summary) { return Object.entries(summary.status_counts || {}).map(([key, value]) => `${statusLabel(key)} ${value} 组`).join('；') }
function download(kind) { window.open(vendorBillingDownloadUrl(id, kind), '_blank') }
onMounted(async () => { try { data.value = await getVendorBilling(id) } catch (error) { ElMessage.error(error.message) } finally { loading.value = false } })
</script>
